const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const longBeach = ee.Geometry.Point([-118.089042, 33.601421]);
  const pismoBeach = ee.Geometry.Point([-120.727924, 35.128348]);

  const targetDate = '2018-08-02';
  const targetYear = 2018;
  const startMonth = 7; // July
  const endMonth = 8; // August
  const startDay = 15; // July 15
  const endDay = 15; // August 15

  // Long-term average period: 2000-2017, same time of year
  const startAvgYear = 2000;
  const endAvgYear = 2017;

  // 2. Data Acquisition
  const sstCollection = ee.ImageCollection('NOAA/CDR/OISST/V2');

  // Filter for the target date (August 2, 2018)
  const sstTargetImage = sstCollection
    .filterDate(targetDate, ee.Date(targetDate).advance(1, 'day'))
    .select('sst');

  // Filter for the long-term average period (July 15 - Aug 15 for 2000-2017)
  const sstAvgCollection = sstCollection.filter(ee.Filter.calendarRange(startMonth, endMonth, 'month'))
    .filter(ee.Filter.calendarRange(startDay, endDay, 'day_of_month'))
    .filter(ee.Filter.calendarRange(startAvgYear, endAvgYear, 'year'))
    .select('sst');

  // Check for empty collections
  const targetImageSize = await sstTargetImage.size().getInfo();
  if (targetImageSize === 0) {
    console.log("No SST data found for August 2, 2018.");
    console.log("C1");
    return;
  }
  const targetImage = sstTargetImage.first();

  const avgCollectionSize = await sstAvgCollection.size().getInfo();
  if (avgCollectionSize === 0) {
    console.log("No SST data found for long-term average period (July 15 - Aug 15, 2000-2017).");
    console.log("C1");
    return;
  }
  const sstAvgImage = sstAvgCollection.mean(); // Calculate mean for the average period

  // Define a larger scale to avoid `maxPixels` issues with point geometry,
  // and OISST data is coarse (0.25 degrees, ~27km at equator).
  const scale = 30000; // ~30 km, slightly larger than OISST native resolution

  // 3. Processing & Calculation
  async function getSSTValues(image, geometry, description) {
    const reducer = ee.Reducer.mean();
    const result = await image.reduceRegion({
      reducer: reducer,
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('sst').getInfo();

    // OISST uses a scaling factor of 100, so divide by 100 for degrees Celsius
    return result !== null ? result / 100.0 : null;
  }

  // Get SST for target date
  const sst_lb_target = await getSSTValues(targetImage, longBeach, "Long Beach (Target)");
  const sst_pb_target = await getSSTValues(targetImage, pismoBeach, "Pismo Beach (Target)");

  // Get long-term average SST
  const sst_lb_avg = await getSSTValues(sstAvgImage, longBeach, "Long Beach (Avg)");
  const sst_pb_avg = await getSSTValues(sstAvgImage, pismoBeach, "Pismo Beach (Avg)");

  // 4. Validation & Final Answer
  if (sst_lb_target === null || sst_pb_target === null || sst_lb_avg === null || sst_pb_avg === null) {
    console.log("C3"); // Calculation Failure (null result from reduceRegion)
    return;
  }

  // Calculate anomalies
  const anomaly_lb = sst_lb_target - sst_lb_avg;
  const anomaly_pb = sst_pb_target - sst_pb_avg;

  console.log(`SST Long Beach (2018-08-02): ${sst_lb_target.toFixed(2)} °C`);
  console.log(`SST Pismo Beach (2018-08-02): ${sst_pb_target.toFixed(2)} °C`);
  console.log(`SST Long Beach (Avg): ${sst_lb_avg.toFixed(2)} °C`);
  console.log(`SST Pismo Beach (Avg): ${sst_pb_avg.toFixed(2)} °C`);
  console.log(`Anomaly Long Beach: ${anomaly_lb.toFixed(2)} °C`);
  console.log(`Anomaly Pismo Beach: ${anomaly_pb.toFixed(2)} °C`);

  if (anomaly_lb > anomaly_pb) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
